from reports_ab import ROOT, OUT
from preflight import digest
import json
paths = sorted([p for p in OUT.glob('03_*.md') if p.name != '03_Checkpoint_Status.md'])
paths += [OUT / '03_Causal_Assumption_Register.csv', OUT / '03_Stage04_Protocol_Lock.csv', OUT / '03_Stage04_Analysis_Priority.csv']
paths += [ROOT / '03_audit_outputs/Stage02' / name for name in ['02_PPML_Code_Audit.md', '02_Missing_Zero_Suppression_Audit.md', '02_Enrollment_Definition_Audit.md', '02_Policy_Source_Audit.md', '02_Policy_Classification_Risks.md', '02_FFS_MCO_Consistency_Audit.md', '02_Current_Figure2_Source_Audit.md', '02_Original_Result_Lineage.md']]
hashes = {str(p.relative_to(ROOT)): digest(p) for p in paths}
(OUT / '_working/review_packet_hashes.json').write_text(json.dumps(hashes, indent=2), encoding='utf-8')
packet = '# Stage03 immutable protocol review packet\n\n2026-10-12 Asia/Shanghai。This is a bounded review of the proposed Stage03 protocol, not a new review of original manuscripts or a claim of external expert review. All proposed analyses are NOT_EXECUTED. Review only the files below, common nature-reviewer criteria and the supplied human task boundaries. Do not read other reviewer reports, issue registers, synthesis or QA drafts. Do not execute models, import historical modules, calculate IRR/CI/P, modify data or manuscripts, install/download, scan personal directories, or start Stage04. Evidence pointers must be actual filename/section/Analysis_ID, no invented page numbers.\n\nOriginal saved estimate 4.09 is MATCHED_SAVED_OUTPUT, not independently reproduced. Report status only CONFIRMED/SUSPECTED/NOT_VERIFIABLE/RESOLVED; confidence HIGH_CONFIDENCE/MEDIUM_CONFIDENCE/LOW_CONFIDENCE/UNKNOWN. Proposed protocol is the review target, including its analytical decisions; do not treat its claims as validated outcomes.\n\nCommon criteria are originality, importance, interdisciplinary interest, technical soundness and nonspecialist readability. Adapt to scientific protocol audit, not Nature acceptance prediction. Include stable local IDs, Major/Minor, Blocking Yes/No, claim pointer, evidence pointer, resolution test; no concern quota. Freeze individual report on completion. Three emphasis briefs preassigned before dispatch: Reviewer1 causal identification; Reviewer2 policy implementation; Reviewer3 computation/data quality.\n\nFiles below are frozen byte identities. Full paths resolve relative to PROJECT_ROOT PROJECT_ROOT. The listed hashes are the common input packet, no other reviewer content.\n\n' + ''.join((f'- `{p}` SHA256 `{h}`\n' for p, h in hashes.items()))
(OUT / '_working/REVIEW_PACKET.md').write_text(packet, encoding='utf-8')
recovery = '# Stage03恢复记录\n\n2026-10-12 Asia/Shanghai。网络中断前已完成强制材料读取、技能读取、原公式静态检查、公开原始文献核验和环境元信息/完整性预检。最后已验证持久化产物仅preflight.py、environment_preflight.json、integrity_before.json、Issue_Register_Stage02_Baseline.csv。A/B/C/D正式报告此前均NOT_STARTED；检查点文件不存在。未把文件存在当任务完成，也未依据mtime判断版本。\n\n恢复核验发现4个上述文件内容完整，预检记录128项目保护文件及82已索引DATA文件哈希，源与Stage02一致，原研究环境NOT_VERIFIABLE。当前全局42项与baseline一致，P0=10/P1=24/P2=8；无P0 RESOLVED。项目无.git，git工作区NOT_APPLICABLE，未扫描父目录仓库。未重复执行Stage00–02；读取旧材料和校验字节只是复用证据。\n\n恢复继续点是A1–A4报告编写/落盘。其后新增A/B/C报告、D的28项规格及原42问题决策列，无问题状态/严重程度变更。后续独立挑战、执行QA和反馈ZIP完成状态详03_Checkpoint_Status.md。无删除/自动丢弃临时文件；所有未执行数值步骤仍NOT_EXECUTED。\n'
(OUT / '03_Recovery_State.md').write_text(recovery, encoding='utf-8')
print('Frozen review files:', len(paths))
